function getPreviousInvoiceQuantity(posInvoice, itemCode) {
  var previousQuantity = 0;

  var previousInvoice = frappe.get_all('POS Invoice Item', {
    parent: posInvoice,
    item_code: itemCode
  }, ['sum(qty) as total_qty'], { order_by: 'creation desc', limit: 1 });

  if (previousInvoice.length > 0) {
    previousQuantity = previousInvoice[0]['total_qty'];
  }

  return previousQuantity;
}

