frappe.ui.form.on('POS Invoice', {
    onload: function(frm) {
        // Define your pos_profile
        var pos_profile = 'طربمة4 بترول';
        // Define your item code
        var item_code = 1111;

        if (frm.doc.POS_Profile === pos_profile ) {
            // Check if the Sales Item table is empty
            if (frm.doc.items.length === 0) {
                // Fetch the rate of the item
                frappe.call({
                    method: 'frappe.client.get_value',
                    args: {
                        'doctype': 'Item',
                        'filters': {'name': item_code},
                        'fieldname': ['standard_rate']
                    },
                    callback: function(response) {
                        var rate = response.message.standard_rate;
                        // Add the item to the Sales Item table with its rate
                        frm.add_child('items', {
                            item_code: item_code,
                            qty: 1,
                            rate: rate
                        });
                        // Refresh the form to reflect the changes
                        frm.refresh_field('items');
                    }
                });
            }
        }
    }
});

frappe.ui.form.on('POS Invoice', {
    onload: function(frm) {
        // تسجيل حدث التغيير على حقل نقطة البيع
        frm.set_df_property('pos_profile', 'onchange', 'auto_populate_items');
    },

    auto_populate_items: function(frm) {
        // التحقق من وجود ملف نقطة البيع
        if (frm.doc.pos_profile) {
            // استرداد بيانات نقطة البيع
            frappe.call({
                method: 'erpnext.accounts.doctype.pos_invoice.pos_invoice.get_items',
                args: {
                    pos_profile: frm.doc.pos_profile
                },
                callback: function(r) {
                    // مسح بنود الفاتورة الحالية
                    frm.clear_table('items');

                    // إضافة البنود الجديدة
                    $.each(r.message, function(i, item) {
                        var row = frm.add_child('items');
                        frappe.model.set_value(row.doctype, row.name, 'item_code', item.item_code);
                        frappe.model.set_value(row.doctype, row.name, 'qty', 1);
                        frappe.model.set_value(row.doctype, row.name, 'rate', item.rate);
                    });

                    // تحديث الفاتورة
                    frm.refresh_field('items');
                }
            });
        }
    }
});

