frappe.ui.form.on('Sales Invoice', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 1) {  // إذا كانت الفاتورة معتمدة
            frm.add_custom_button(__('🔧 تعديل الفاتورة'), function () {
                frappe.msgprint(__('تم تفعيل التعديل. لا تنسَ الضغط على "حفظ" بعد التعديل.'));

                // فك الحماية عن الحقول المطلوبة
                frm.fields.forEach(function(field) {
                    frm.set_df_property(field.df.fieldname, 'read_only', 0);
                });

                // فك الحماية عن الحقول داخل جدول الأصناف
                if (frm.fields_dict.items) {
                    frm.fields_dict.items.grid.update_docfield_property('qty', 'read_only', 0);
                    frm.fields_dict.items.grid.update_docfield_property('rate', 'read_only', 0);
                    frm.fields_dict.items.grid.update_docfield_property('item_name', 'read_only', 0);
                    frm.fields_dict.items.grid.update_docfield_property('item_code', 'read_only', 0);
                }

                frm.refresh_fields();
            });
        }
    }
});


