frappe.listview_settings['Sales Invoice'] = {
    onload: function(listview) {
        const pos_profile = "نقد";
        const customer_name = "عميل نقدي";

        async function create_invoice(is_return = 0, is_pos = 1) {
            const new_invoice = frappe.model.get_new_doc('Sales Invoice');

            new_invoice.is_return = is_return;
            new_invoice.is_pos = is_pos;

            if (!is_return && is_pos) {
                const profile_doc = await frappe.db.get_doc("POS Profile", pos_profile);
                const cash_account = profile_doc.payments.find(p => p.mode_of_payment === "Cash")?.account;

                new_invoice.pos_profile = pos_profile;
                new_invoice.customer = customer_name;

                new_invoice.payments = [{
                    mode_of_payment: "Cash",
                    account: cash_account,
                    amount: 0
                }];
            }

            frappe.set_route('Form', 'Sales Invoice', new_invoice.name);
        }

        async function create_sales_return_from_invoice(docname) {
            try {
                const source = await frappe.db.get_doc("Sales Invoice", docname);

                if (source.is_return) {
                    frappe.msgprint("❌ لا يمكن إنشاء مرتجع لفاتورة هي أصلاً مرتجع.");
                    return;
                }

                const returned_invoices = await frappe.db.get_list("Sales Invoice", {
                    filters: {
                        docstatus: 1,
                        is_return: 1,
                        return_against: docname
                    },
                    fields: ["name"]
                });

                let returned_items = {};
                for (let inv of returned_invoices) {
                    let return_doc = await frappe.db.get_doc("Sales Invoice", inv.name);
                    for (let item of return_doc.items) {
                        if (!returned_items[item.item_code]) {
                            returned_items[item.item_code] = 0;
                        }
                        returned_items[item.item_code] += Math.abs(item.qty);
                    }
                }

                let new_doc = frappe.model.get_new_doc('Sales Invoice');
                new_doc.is_return = 1;
                new_doc.return_against = source.name;
                new_doc.customer = source.customer;
                new_doc.posting_date = frappe.datetime.nowdate();
                new_doc.posting_time = frappe.datetime.now_time();
                new_doc.is_pos = source.is_pos;
                new_doc.pos_profile = source.pos_profile;
                new_doc.items = [];

                for (let item of source.items) {
                    const total_qty = item.qty;
                    const returned_qty = returned_items[item.item_code] || 0;
                    const remaining_qty = total_qty - returned_qty;

                    if (remaining_qty > 0) {
                        new_doc.items.push({
                            item_code: item.item_code,
                            item_name: item.item_name,
                            qty: -remaining_qty,
                            rate: item.rate,
                            uom: item.uom,
                            conversion_factor: item.conversion_factor,
                            warehouse: item.warehouse
                        });
                    }
                }

                if (new_doc.items.length === 0) {
                    frappe.msgprint("⚠️ كل أصناف هذه الفاتورة تم إرجاعها مسبقًا.");
                    return;
                }

                frappe.model.sync(new_doc);
                frappe.set_route("Form", "Sales Invoice", new_doc.name);

            } catch (e) {
                console.error(e);
                frappe.msgprint("حدث خطأ أثناء إنشاء فاتورة المرتجع.");
            }
        }

        // زر فاتورة نقدية
        listview.page.add_inner_button(__('📥 إضافة فاتورة نقدية'), function () {
            create_invoice(0, 1);
        });

        // زر مرتجع مبيعات
        listview.page.add_inner_button(__('🔄 مرتجع مبيعات'), async function () {
            const selected = listview.get_checked_items();

            if (selected.length === 1) {
                await create_sales_return_from_invoice(selected[0].name);
            } else if (selected.length === 0) {
                // فتح نموذج مرتجع عام بدون pos_profile أو دفع
                await create_invoice(1, 0);
            } else {
                frappe.msgprint("⚠️ يرجى تحديد فاتورة واحدة فقط لإنشاء مرتجع.");
            }
        });
    }
};

