frappe.ui.form.on('Sales Invoice', {
    custom_enable_tax(frm) {
        if (frm.doc.custom_enable_tax) {
            // إظهار الحقول
            frm.set_df_property('taxes_and_charges', 'hidden', 0);
            frm.set_df_property('taxes', 'hidden', 0);

            // تعبئة القالب الافتراضي تلقائيًا إذا لم يتم اختياره
            if (!frm.doc.taxes_and_charges) {
                frappe.db.get_value("Sales Taxes and Charges Template", { is_default: 1 }, "name")
                    .then(r => {
                        if (r && r.message && r.message.name) {
                            frm.set_value("taxes_and_charges", r.message.name);
                        }
                    });
            }
        } else {
            // إخفاء الحقول وحذف القيم
            frm.set_value("taxes_and_charges", null);
            frm.clear_table("taxes");

            frm.set_df_property('taxes_and_charges', 'hidden', 1);
            frm.set_df_property('taxes', 'hidden', 1);
        }
        frm.refresh_fields();
    },

    onload_post_render(frm) {
        // لضبط الحالة عند تحميل النموذج
        frm.trigger("custom_enable_tax");
    }
});

