                }
                .row-check {
                    height: 38px;
                    text-align: center;
                }
                .col {
                    flex-basis: 0;
                    flex-grow: 1;
                    max-width: min-content;
                }
            `;
            // إدراج الكود في الصفحة
            if (!document.getElementById("mobile-custom-style")) {
                let styleTag = document.createElement("style");
                styleTag.id = "mobile-custom-style";
                styleTag.innerHTML = style;
                document.head.appendChild(styleTag);
            }
        }
